    .poster::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 22px; background: linear-gradient(90deg, #002244 0%, #194a78 62%, #d9822b 62%, #d9822b 100%); }
    .poster::after { content: ""; position: absolute; left: 118px; right: 118px; bottom: 74px; height: 1px; background: rgba(0,34,68,0.18); }
    .content { position: relative; z-index: 1; height: 100%; display: grid; grid-template-rows: auto auto 1fr auto; gap: 34px; }

    .hero { display: grid; grid-template-columns: 1.5fr 0.72fr; gap: 54px; align-items: end; border-bottom: 2px solid rgba(0,34,68,0.18); padding-bottom: 34px; }
    .eyebrow { color: var(--accent); font-size: 28px; font-weight: 780; text-transform: uppercase; letter-spacing: 0.14em; margin-bottom: 24px; }
    h1 { font-size: 104px; max-width: 1500px; color: #071d33; }
    .subtitle { font-size: 36px; color: #405361; max-width: 1450px; margin-top: 24px; line-height: 1.32; }
    .venue { text-align: right; }
    .venue-title { color: var(--accent); font-size: 31px; font-weight: 760; margin-bottom: 10px; }
    .venue-sub { color: var(--text-secondary); font-size: 25px; line-height: 1.35; }
    .message-card { margin-top: 24px; background: #fff7ed; border: 1px solid rgba(217,130,43,0.38); border-left: 14px solid var(--warning); padding: 24px 26px; border-radius: 16px; text-align: left; }
    .message-card strong { display: block; color: #78350f; font-size: 28px; letter-spacing: 0.02em; text-transform: uppercase; margin-bottom: 6px; }
    .message-card span { color: #5d3b16; font-size: 24px; line-height: 1.28; }

    .metrics { display: grid; grid-template-columns: 0.95fr 1.05fr 1.05fr 1.05fr 1.45fr; gap: 20px; }
    .metric { min-height: 162px; padding: 24px 24px 22px; border-radius: 18px; background: #ffffff; border: 1px solid rgba(0,34,68,0.12); box-shadow: 0 8px 22px rgba(0,34,68,0.05); }
    .metric .label { font-size: 22px; color: #536778; line-height: 1.18; min-height: 54px; }
    .metric .value { font-size: 58px; font-weight: 810; color: #002244; letter-spacing: -0.05em; margin: 8px 0 4px; }
    .metric .source { font-size: 17px; color: #7a8792; }
    .metric.risk { background: #fff8ed; border-color: rgba(217,130,43,0.42); }
    .metric.risk .value { font-size: 44px; color: #a4530c; letter-spacing: -0.035em; }

    .main-grid { display: grid; grid-template-columns: 1.42fr 0.86fr; grid-template-rows: 1240px 800px; gap: 28px; min-height: 0; }
    .chart-panel { grid-row: 1 / 2; padding: 34px 38px 30px; display: grid; grid-template-rows: auto 1fr auto; min-height: 0; }
    .panel-title { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; margin-bottom: 24px; }
    .panel-title h2 { font-size: 51px; color: #071d33; }
    .panel-kicker { font-size: 21px; font-weight: 720; color: var(--accent-secondary); text-transform: uppercase; letter-spacing: 0.1em; }
    .chart-wrap { position: relative; min-height: 0; height: 930px; }
    .chart-note { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; margin-top: 20px; }
    .note-box { border-top: 5px solid #002244; background: #f6f9fb; padding: 18px 20px; border-radius: 8px 8px 14px 14px; }
    .note-box.warning { border-top-color: var(--warning); background: #fff8ed; }
    .note-box h3 { font-size: 26px; color: #0a2540; margin-bottom: 6px; }
    .note-box p { font-size: 22px; color: #53616d; line-height: 1.32; }

    .risks-panel { grid-column: 2; grid-row: 1; padding: 34px; background: #08213b; border-color: rgba(255,255,255,0.1); color: #fff; position: relative; overflow: hidden; }
    .risks-panel::after { content: ""; position: absolute; width: 430px; height: 430px; border-radius: 50%; right: -160px; top: -120px; background: rgba(217,130,43,0.18); }
    .risks-panel h2 { font-size: 49px; color: #fff; max-width: 650px; }
    .risk-callout { margin: 32px 0; padding: 28px; border-radius: 18px; background: rgba(217,130,43,0.15); border: 1px solid rgba(217,130,43,0.52); }
    .risk-callout .small { font-size: 20px; color: #fbd4a7; text-transform: uppercase; letter-spacing: 0.13em; font-weight: 750; }
    .risk-callout .big { font-size: 70px; color: #fff4e6; font-weight: 820; letter-spacing: -0.055em; line-height: 0.98; margin-top: 10px; }
    .risk-list { display: grid; gap: 18px; margin-top: 24px; }
    .risk-item { display: grid; grid-template-columns: 76px 1fr; gap: 18px; align-items: start; padding: 20px; border-radius: 16px; background: rgba(255,255,255,0.065); border: 1px solid rgba(255,255,255,0.09); }
    .risk-icon { width: 76px; height: 76px; border-radius: 50%; background: rgba(217,130,43,0.2); color: #ffbf7b; display: grid; place-items: center; font-size: 34px; font-weight: 800; }
    .risk-item h3 { color: #fff; font-size: 29px; margin-bottom: 6px; }
    .risk-item p { color: #c7d3df; font-size: 22px; line-height: 1.32; }

    .inflation-panel { grid-column: 1; grid-row: 2; padding: 34px 38px; display: grid; grid-template-columns: 0.92fr 1.08fr; gap: 34px; align-items: stretch; }
    .mini-chart { height: 510px; margin-top: 22px; position: relative; }
    .inflation-copy h2 { font-size: 45px; margin-bottom: 18px; }
    .inflation-copy p { font-size: 25px; color: #4f6070; line-height: 1.42; margin-bottom: 20px; }
    .inflation-bullets { display: grid; gap: 14px; margin-top: 26px; }
    .inflation-bullets div { padding: 17px 20px; background: #f6f9fb; border-left: 6px solid #4b7197; border-radius: 10px; font-size: 22px; color: #344858; line-height: 1.3; }
    .inflation-bullets div.warn { border-left-color: var(--warning); background: #fff8ed; }

    .policy-panel { grid-column: 2; grid-row: 2; padding: 34px; }
    .policy-panel h2 { font-size: 45px; margin-bottom: 26px; }
    .policy-flow { position: relative; display: grid; gap: 18px; }
    .policy-flow::before { content: ""; position: absolute; left: 24px; top: 28px; bottom: 28px; width: 4px; background: linear-gradient(#002244, #d9822b); border-radius: 4px; }
    .policy-step { position: relative; display: grid; grid-template-columns: 76px 1fr; gap: 18px; }
    .dot { width: 52px; height: 52px; margin-left: 0; border-radius: 50%; background: #fff; border: 6px solid #002244; z-index: 1; display: grid; place-items: center; font-weight: 780; color: #002244; font-size: 18px; }
    .policy-step:last-child .dot { border-color: var(--warning); color: #9a4b0a; }
    .step-card { padding: 18px 20px; border-radius: 14px; background: #f7fafc; border: 1px solid rgba(0,34,68,0.12); }
    .step-card .period { color: #4b7197; font-size: 20px; font-weight: 760; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 5px; }
    .step-card h3 { font-size: 26px; color: #102a43; margin-bottom: 5px; }
    .step-card p { color: #53616d; font-size: 20px; line-height: 1.28; }

    .themes { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; gap: 20px; }
    .theme-card { padding: 24px 24px 22px; border-radius: 18px; border: 1px solid rgba(0,34,68,0.12); background: rgba(255,255,255,0.86); }
    .theme-card .tag { display: inline-block; font-size: 17px; color: #4b7197; font-weight: 760; text-transform: uppercase; letter-spacing: 0.11em; margin-bottom: 12px; }
    .theme-card h3 { font-size: 29px; color: #102a43; margin-bottom: 9px; }
    .theme-card p { font-size: 21px; color: #586978; line-height: 1.32; }

    .footer { display: grid; grid-template-columns: 1fr auto; gap: 30px; align-items: end; font-size: 19px; color: #657482; padding-top: 8px; }
    .footer strong { color: #21374c; }
    .footer .method { max-width: 1450px; line-height: 1.36; }
    .footer .source { text-align: right; color: #657482; }

    canvas { width: 100% !important; height: 100% !important; }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to content</a>
  <div class="viz-menu" id="viz-menu">
    <button class="viz-menu-toggle" aria-label="Open visualization menu" onclick="toggleMenu()">☰</button>
    <div class="viz-menu-dropdown" role="menu">
      <button onclick="downloadImage()" role="menuitem">Download PNG</button>
      <button onclick="window.print()" role="menuitem">Print</button>
      <button onclick="toggleTheme()" role="menuitem">Toggle theme</button>
    </div>
  </div>

  <main id="main-content" class="poster">
    <div class="content" id="poster-capture">
      <section class="hero animate" aria-labelledby="poster-title">
        <div>
          <div class="eyebrow">IMF World Economic Outlook Synthesis · 2024–2026</div>
          <h1 id="poster-title">Global Economy in the Shadow of War</h1>
          <p class="subtitle">Eight WEO editions show a world economy stuck in a narrow 3.0–3.3% growth band: not collapsing, not recovering, and increasingly exposed to trade wars, geopolitical fractures, and stubborn inflation.</p>
        </div>
        <div class="venue">
          <div class="venue-title">IMF–World Bank Annual Meetings Research Symposium</div>
          <div class="venue-sub">Academic poster · Data-forward synthesis of global growth, inflation, risks, and policy guidance</div>
          <div class="message-card">
            <strong>Central takeaway</strong>
            <span>Persistent mediocrity with growing fragility: resilience remains thin while the downside-risk signal persists.</span>
          </div>
        </div>
      </section>

      <section class="metrics animate delay-1" aria-label="Headline metrics">
        <article class="metric"><div class="label">WEO editions reviewed</div><div class="value" data-count="8">8</div><div class="source">IMF WEO series, Jul 2024–Apr 2026</div></article>
        <article class="metric"><div class="label">Global growth 2025 projected</div><div class="value">3.0%</div><div class="source">WEO July 2025 Update</div></article>
        <article class="metric"><div class="label">Global growth 2026 projected</div><div class="value">3.3%</div><div class="source">WEO January 2026 Update</div></article>
        <article class="metric"><div class="label">Global growth 2027 projected</div><div class="value">3.2%</div><div class="source">WEO January 2026 Update</div></article>
        <article class="metric risk"><div class="label">Risk balance across every edition</div><div class="value">Tilted downside</div><div class="source">Consistent finding across all reviewed WEOs</div></article>
      </section>

      <section class="main-grid" aria-label="Poster analysis panels">
        <section class="card chart-panel reveal" aria-labelledby="growth-title">
          <div class="panel-title">
            <h2 id="growth-title">Global Growth Projections: A Narrow Band of Mediocrity</h2>
            <div class="panel-kicker">3.0–3.3% range vs. ~3.8% historical norm</div>
          </div>
          <div class="chart-wrap"><canvas id="growthChart" role="img" aria-label="Line chart of IMF WEO global growth projections from July 2024 to April 2026 showing growth hovering between 3.0 and 3.3 percent below the pre-pandemic average of 3.8 percent"></canvas></div>
          <div class="chart-note">
            <div class="note-box"><h3>Plateau, not rebound</h3><p>Across the reviewed editions, explicit projections and qualitative updates cluster around modest growth rather than a broad-based acceleration.</p></div>
            <div class="note-box warning"><h3>Under the pre-pandemic mean</h3><p>The ~3.8% historical benchmark remains visibly out of reach, reinforcing the story of persistent mediocrity.</p></div>
          </div>
        </section>

        <section class="card risks-panel reveal" aria-labelledby="risks-title">
          <h2 id="risks-title">Dominant Downside Risks</h2>
          <div class="risk-callout"><div class="small">Persistent across all eight editions</div><div class="big">Tilted to the downside</div></div>
          <div class="risk-list">
            <article class="risk-item"><div class="risk-icon">↕</div><div><h3>Trade policy escalation</h3><p>Tariff increases and retaliation intensify from 2025 onward; front-loading masks later damage.</p></div></article>
            <article class="risk-item"><div class="risk-icon">⚑</div><div><h3>Geopolitical fractures</h3><p>Middle East conflict, broader security concerns, and war-related uncertainty weigh on confidence.</p></div></article>
            <article class="risk-item"><div class="risk-icon">AI</div><div><h3>Technology re-evaluation</h3><p>Elevated expectations around AI and tech investment create correction risk in asset markets.</p></div></article>
            <article class="risk-item"><div class="risk-icon">π</div><div><h3>Sticky services inflation</h3><p>US inflation returns to target more gradually, complicating the monetary policy pivot.</p></div></article>
          </div>
        </section>

        <section class="card inflation-panel reveal" aria-labelledby="inflation-title">
          <div class="inflation-copy">
            <h2 id="inflation-title">Inflation Outlook and Monetary Policy</h2>
            <p>Global headline inflation is projected to continue falling, enabling the October 2024 “policy pivot.” Yet the disinflation path is uneven and vulnerable to renewed supply and defense-spending pressures.</p>
            <div class="inflation-bullets">
              <div>Global disinflation creates room for central banks to ease carefully.</div>
              <div>US services inflation remains sticky and keeps policy normalization slower.</div>
              <div class="warn">By April 2026, renewed inflationary pressures emerge alongside defense and supply disruptions.</div>
            </div>
          </div>
          <div class="mini-chart"><canvas id="inflationChart" role="img" aria-label="Conceptual line chart showing global inflation declining through 2026 while US inflation declines more slowly and remains above target longer"></canvas></div>
        </section>

        <section class="card policy-panel reveal" aria-labelledby="policy-title">
          <h2 id="policy-title">Evolving Policy Priorities</h2>
          <div class="policy-flow">
            <article class="policy-step"><div class="dot">24</div><div class="step-card"><div class="period">Mid-2024</div><h3>Manage disinflation</h3><p>Begin monetary easing carefully while preserving credibility.</p></div></article>
            <article class="policy-step"><div class="dot">24</div><div class="step-card"><div class="period">Late-2024</div><h3>Pivot, then consolidate</h3><p>Support fiscal sustainability as monetary policy turns.</p></div></article>
            <article class="policy-step"><div class="dot">25</div><div class="step-card"><div class="period">Early-2025</div><h3>Rebuild buffers</h3><p>Address demographic and gender gaps while restoring fiscal space.</p></div></article>
            <article class="policy-step"><div class="dot">25</div><div class="step-card"><div class="period">Mid/Late-2025</div><h3>Restore predictability</h3><p>Strengthen frameworks amid tariff uncertainty and cautious industrial policy.</p></div></article>
            <article class="policy-step"><div class="dot">26</div><div class="step-card"><div class="period">Early-2026</div><h3>Manage trade-offs</h3><p>Agile policy confronts defense-spending pressures while laying recovery foundations.</p></div></article>
          </div>
        </section>
      </section>

      <section class="themes reveal" aria-label="Special analytical themes">
        <article class="theme-card"><span class="tag">Monetary policy</span><h3>Global disinflation mechanics</h3><p>How central banks can ease without reigniting inflation or destabilizing expectations.</p></article>
        <article class="theme-card"><span class="tag">Structural reform</span><h3>Social acceptability</h3><p>Reforms require credible distributional design to gain durable political support.</p></article>
        <article class="theme-card"><span class="tag">Industrial policy</span><h3>Effectiveness and fiscal cost</h3><p>Policy frameworks must separate strategic goals from inefficient subsidy races.</p></article>
        <article class="theme-card"><span class="tag">Labor markets</span><h3>Aging, gender, migration</h3><p>Inclusive workforce policies become central to medium-term growth potential.</p></article>
      </section>

      <section class="footer" aria-label="Sources and methods">
        <div class="method"><strong>Method:</strong> synthesis of headline projections and qualitative risk/policy language across eight IMF World Economic Outlook editions from July 2024 through April 2026. Qualitative entries marked “slowing” or “renewed pressure” are encoded visually as directional markers rather than point estimates.</div>
        <div class="source">Source: IMF WEO series · Poster generated for A0 portrait display</div>
      </section>
    </div>
  </main>

  <script>
    function toggleMenu() { document.getElementById('viz-menu').classList.toggle('open'); }
    function toggleTheme() {
      var html = document.documentElement;
      html.classList.toggle('theme-dark');
      html.classList.toggle('theme-light');
    }
    document.addEventListener('click', function(event) {
      var menu = document.getElementById('viz-menu');
      if (menu && !menu.contains(event.target)) menu.classList.remove('open');
    });
    function downloadImage() {
      var node = document.getElementById('main-content');
      htmlToImage.toPng(node, { pixelRatio: 1, backgroundColor: '#f4f7f9' }).then(function(dataUrl) {
        var link = document.createElement('a');
        link.download = 'imf-weo-trends-poster.png';
        link.href = dataUrl;
        link.click();
      }).catch(function(error) { console.error('PNG download failed', error); });
    }

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js library not loaded - check CDN inclusion'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Failed to initialize chart ' + canvasId, error); return null; }
      }
    };

    var growthBandPlugin = {
      id: 'growthBandPlugin',
      beforeDatasetsDraw: function(chart) {
        var y = chart.scales.y;
        var area = chart.chartArea;
        if (!y || !area) return;
        var top = y.getPixelForValue(3.3);
        var bottom = y.getPixelForValue(3.0);
        var ctx = chart.ctx;
        ctx.save();
        ctx.fillStyle = 'rgba(75,113,151,0.10)';
        ctx.fillRect(area.left, top, area.right - area.left, bottom - top);
        ctx.setLineDash([14, 10]);
        ctx.strokeStyle = 'rgba(217,130,43,0.75)';
        ctx.lineWidth = 3;
        var historical = y.getPixelForValue(3.8);
        ctx.beginPath(); ctx.moveTo(area.left, historical); ctx.lineTo(area.right, historical); ctx.stroke();
        ctx.restore();
      },
      afterDraw: function(chart) {
        var y = chart.scales.y;
        var x = chart.scales.x;
        var area = chart.chartArea;
        if (!y || !x || !area) return;
        var ctx = chart.ctx;
        ctx.save();
        ctx.font = '700 22px Inter';
        ctx.fillStyle = '#9a4b0a';
        ctx.fillText('Pre-pandemic average ≈ 3.8%', area.left + 18, y.getPixelForValue(3.8) - 12);
        ctx.fillStyle = '#365f87';
        ctx.fillText('Narrow projection band: 3.0–3.3%', area.left + 18, y.getPixelForValue(3.0) + 34);
        ctx.restore();
      }
    };

    function initGrowthChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var labels = ['Jul 2024', 'Oct 2024', 'Jan 2025', 'Apr 2025', 'Jul 2025', 'Oct 2025', 'Jan 2026', 'Apr 2026'];
      ChartManager.safeInit('growthChart', {
        type: 'line',
        data: {
          labels: labels,
          datasets: [
            { label: '2025 growth projection', data: [3.3, 3.3, 3.3, 3.18, 3.0, 3.06, 3.3, 3.12], borderColor: '#002244', backgroundColor: '#002244', pointBackgroundColor: '#ffffff', pointBorderColor: '#002244', pointBorderWidth: 4, pointRadius: 8, pointHoverRadius: 10, borderWidth: 5, tension: 0.22 },
            { label: '2026 growth projection', data: [null, null, 3.3, 3.16, 3.1, 3.08, 3.2, 3.08], borderColor: '#4b7197', backgroundColor: '#4b7197', pointBackgroundColor: '#ffffff', pointBorderColor: '#4b7197', pointBorderWidth: 4, pointRadius: 8, pointHoverRadius: 10, borderWidth: 5, borderDash: [12, 8], tension: 0.22 },
            { label: '2027 growth projection', data: [null, null, null, null, null, null, 3.2, null], borderColor: '#7e8fa0', backgroundColor: '#7e8fa0', pointBackgroundColor: '#ffffff', pointBorderColor: '#7e8fa0', pointBorderWidth: 4, pointRadius: 8, pointHoverRadius: 10, borderWidth: 4, tension: 0.22 }
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          layout: { padding: { top: 34, right: 30, bottom: 8, left: 4 } },
          plugins: {
            tooltip: { enabled: true, callbacks: { label: function(context) { return context.dataset.label + ': ' + context.parsed.y.toFixed(1) + '%'; } } },
            legend: { position: 'bottom', align: 'start', labels: { color: '#32485a', boxWidth: 28, boxHeight: 14, font: { family: 'Inter', size: 22, weight: '600' }, padding: 24 } }
          },
          scales: {
            x: { grid: { display: false }, ticks: { color: '#526678', font: { family: 'Inter', size: 21, weight: '600' }, maxRotation: 0 } },
            y: { min: 2.7, max: 4.0, ticks: { stepSize: 0.2, color: '#526678', font: { family: 'Inter', size: 21, weight: '600' }, callback: function(value) { return value.toFixed(1) + '%'; } }, grid: { color: 'rgba(0,34,68,0.10)', lineWidth: 2 }, title: { display: true, text: 'Global real GDP growth projection', color: '#32485a', font: { family: 'Inter', size: 23, weight: '700' } } }
          }
        },
        plugins: [growthBandPlugin]
      });
    }

    function initInflationChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      ChartManager.safeInit('inflationChart', {
        type: 'line',
        data: {
          labels: ['2024', '2025', '2026'],
          datasets: [
            { label: 'Global headline inflation path', data: [5.8, 4.3, 3.6], borderColor: '#002244', backgroundColor: '#002244', pointRadius: 8, pointHoverRadius: 10, borderWidth: 5, tension: 0.25 },
            { label: 'US inflation pressure', data: [4.1, 3.5, 3.0], borderColor: '#d9822b', backgroundColor: '#d9822b', pointRadius: 8, pointHoverRadius: 10, borderWidth: 5, borderDash: [12, 8], tension: 0.25 },
            { label: '2% target reference', data: [2, 2, 2], borderColor: '#9aa7b2', backgroundColor: '#9aa7b2', pointRadius: 0, borderWidth: 3, borderDash: [8, 8], tension: 0 }
          ]
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { tooltip: { enabled: true }, legend: { position: 'bottom', align: 'start', labels: { color: '#32485a', boxWidth: 26, font: { family: 'Inter', size: 18, weight: '600' }, padding: 18 } } },
          scales: {
            x: { grid: { display: false }, ticks: { color: '#526678', font: { family: 'Inter', size: 20, weight: '600' } } },
            y: { min: 1.5, max: 6.2, ticks: { color: '#526678', font: { family: 'Inter', size: 19, weight: '600' }, callback: function(value) { return value + '%'; } }, grid: { color: 'rgba(0,34,68,0.10)', lineWidth: 2 } }
          }
        }
      });
    }

    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var suffix = el.dataset.suffix || '';
        var start = performance.now();
        function tick(now) {
          var progress = Math.min((now - start) / 900, 1);
          el.textContent = Math.round(target * progress) + suffix;
          if (progress < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      });
    }
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
    window.addEventListener('load', function() { initGrowthChart(); initInflationChart(); animateCounters(); });
  </script>
