        ctx.setLineDash([14, 10]);
        ctx.strokeStyle = 'rgba(217,130,43,0.75)';
        ctx.lineWidth = 3;
        var historical = y.getPixelForValue(3.8);
        ctx.beginPath(); ctx.moveTo(area.left, historical); ctx.lineTo(area.right, historical); ctx.stroke();
        ctx.restore();
      },
      afterDraw: function(chart) {
