const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 2480, height: 3508 }, deviceScaleFactor: 1 });
  await page.goto('file://' + path.resolve('/app/output_poster.html'), { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);
  await page.evaluate(() => {
    document.querySelectorAll('.reveal').forEach(el => el.classList.add('visible'));
    const menu = document.querySelector('.viz-menu');
    if (menu) menu.style.display = 'none';
  });
  const poster = await page.$('#main-content');
  await poster.screenshot({ path: '/app/output/final_poster.png', omitBackground: false });
  await browser.close();
})();
